// Assume kB = 1.0 (reduced units)
const double kB = 1.0;

// Seed the random number generator (only once, but this is a function body)
// Note: In production, consider using <random> for better randomness

for (size_t i = 0; i < velocities.size(); ++i) {
    // Generate a uniform random number in [0, 1)
    double u = static_cast<double>(std::rand()) / RAND_MAX;

    // Check if a collision occurs
    if (u < collisionFreq * dt) {
        // Calculate standard deviation for velocity components
        double sigma_v = std::sqrt(kB * targetTemp / masses[i]);

        // Box-Muller transform for Gaussian random numbers
        double u1 = static_cast<double>(std::rand()) / RAND_MAX;
        double u2 = static_cast<double>(std::rand()) / RAND_MAX;
        double z0 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);

        double u3 = static_cast<double>(std::rand()) / RAND_MAX;
        double u4 = static_cast<double>(std::rand()) / RAND_MAX;
        double z1 = std::sqrt(-2.0 * std::log(u3)) * std::cos(2.0 * M_PI * u4);

        double u5 = static_cast<double>(std::rand()) / RAND_MAX;
        double u6 = static_cast<double>(std::rand()) / RAND_MAX;
        double z2 = std::sqrt(-2.0 * std::log(u5)) * std::cos(2.0 * M_PI * u6);

        // Assign new velocities
        velocities[i].x = sigma_v * z0;
        velocities[i].y = sigma_v * z1;
        velocities[i].z = sigma_v * z2;
    }
}

